namespace sv_303848a21679421183e27578d823cc8f.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_303848a21679421183e27578d823cc8f.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

<div class="d-flex flex-row gap-4">
    @* ===== LEFT SIDEBAR (filters) ===== *@
    <div style="min-width:250px;max-width:25%;flex:0 0 25%;">
        <div class="card">
            <div class="card-header fw-semibold">Filters</div>
            <div class="card-body">
                @* Categories *@
                <h6>Category</h6>
                @if (categories is not null)
                {
                    @foreach (var cat in categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                   checked="@selectedCategories.Contains(cat)"
                                   @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                        </div>
                    }
                }
                else
                {
                    <p class="text-muted small">Loading…</p>
                }

                <hr />

                @* Price range *@
                <h6>Price Range</h6>
                <div class="row g-2 mb-2">
                    <div class="col-6">
                        <input type="number" class="form-control form-control-sm" placeholder="Min"
                               @bind="minPrice" @bind:event="onchange" min="0" step="0.01" />
                    </div>
                    <div class="col-6">
                        <input type="number" class="form-control form-control-sm" placeholder="Max"
                               @bind="maxPrice" @bind:event="onchange" min="0" step="0.01" />
                    </div>
                </div>

                <hr />

                @* In Stock *@
                <div class="form-check mb-3">
                    <input class="form-check-input" type="checkbox" id="inStockOnly"
                           @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>

                @* Buttons *@
                <div class="d-grid gap-2">
                    <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
                    <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
                </div>
            </div>
        </div>
    </div>

    @* ===== MAIN CONTENT ===== *@
    <div style="flex:1 1 75%;min-width:0;">

        @if (errorMessage is not null)
        {
            <div class="alert alert-danger">@errorMessage</div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary me-2" role="status"></div>
                <span>Loading products…</span>
            </div>
        }
        else if (result is not null && result.Items.Count > 0)
        {
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div>
                    <label class="form-label mb-0 me-2 fw-semibold" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                            @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted">
                    Showing @(firstItem)–@(lastItem) of @(result.TotalCount) products
                </span>
            </div>

            @* Product grid *@
            <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                @foreach (var product in result.Items)
                {
                    <div class="col">
                        <div class="card h-100 shadow-sm product-card" role="button"
                             @onclick="() => OnProductSelected(product)">
                            @* Placeholder image *@
                            <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
                                 style="height:180px;" title="@product.Name">
                                <span class="text-muted small">@product.Name</span>
                            </div>
                            <div class="card-body d-flex flex-column">
                                <h6 class="card-title mb-1">@product.Name</h6>
                                <p class="fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                <p class="mb-1">@RenderStars(product.Rating)</p>
                                @if (!product.InStock)
                                {
                                    <span class="badge bg-danger mb-2" style="width:fit-content;">Out of Stock</span>
                                }
                                <div class="mt-auto">
                                    <button class="btn btn-sm btn-success w-100"
                                            disabled="@(!product.InStock)"
                                            @onclick="() => AddToCart(product)"
                                            @onclick:stopPropagation="true">
                                        Add to Cart
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                }
            </div>

            @* Pagination *@
            <nav class="mt-4" aria-label="Product pagination">
                <ul class="pagination justify-content-center flex-wrap">
                    <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage == 1)">Previous</button>
                    </li>
                    @for (int i = 1; i <= totalPages; i++)
                    {
                        var pageNum = i;
                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                        </li>
                    }
                    <li class="page-item @(currentPage == totalPages ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage == totalPages)">Next</button>
                    </li>
                </ul>
            </nav>
        }
        else if (result is not null)
        {
            <div class="alert alert-info">No products found matching your filters.</div>
        }
    </div>
</div>

@code {
    /// <summary>Raised when a product card is clicked (not the Add to Cart button).</summary>
    [Parameter] public EventCallback<Product> OnProductClicked { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? result;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Paging / sorting
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;

    // UI state
    private bool isLoading;
    private string? errorMessage;

    // Computed helpers
    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int firstItem => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int lastItem => result is null || result.Items.Count == 0
        ? 0
        : firstItem + result.Items.Count - 1;

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await SearchProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = new List<string>();
        }
    }

    private async Task SearchProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products. Please try again. ({ex.Message})";
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        sortBy = "price_asc";
        await SearchProducts();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await SearchProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > totalPages) return;
        currentPage = page;
        await SearchProducts();
    }

    private async Task OnProductSelected(Product product)
    {
        if (OnProductClicked.HasDelegate)
            await OnProductClicked.InvokeAsync(product);
    }

    private void AddToCart(Product product)
    {
        // Placeholder – wire up to a cart service as needed
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        int empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}

.product-card {
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 .5rem 1rem rgba(0, 0, 0, .15) !important;
}

